package mod.cdv.tnpc.tactical;import java.util.*;public class CalmBrain{static Map<Object,State> states=new WeakHashMap<>();static State state(Object n){return states.computeIfAbsent(n,k->new State());}static boolean gun(Object n){return ((fixture.Entity)n).getMainHandItem().id.equals("tacz:gun");}static void crouch(Object n,boolean v){((fixture.Entity)n).shift=v;}static final class State{Object target;Object corpse;long reactAt,seen,nextPath;int zombies;}}